// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    address deployer;

    function setUp() public {
        deployer = address(this);
        c = new Owned();
    }

    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0));

        address initialOwner = c.owner();
        assertTrue(initialOwner == deployer);

        vm.prank(deployer);
        bool ok;
        try c.setOwner(actor) {
            ok = true;
        } catch {
            ok = false;
        }
        vm.assume(ok);

        address newOwner = address(uint160(uint256(keccak256(abi.encodePacked(actor, "new")))));

        vm.prank(actor);
        bool ok2;
        try c.setOwner(newOwner) {
            ok2 = true;
        } catch {
            ok2 = false;
        }

        assertTrue(!ok2);
    }
}
